const ai = $('Message a model').first().json;
const jobOutput = $('Get Job Requisition').first().json;

// Extract the resume JSON from common n8n AI output formats.
function getAIContent(data) {
  const candidates = [
    data.output,
    data.text,
    data.content,
    data.message?.content,
    data.output?.[0]?.content?.[0]?.text,
    data.content?.[0]?.text,
  ];

  for (const candidate of candidates) {
    if (candidate && typeof candidate === 'object') {
      if (
        candidate.error &&
        !candidate.fullName &&
        !candidate.primarySkills
      ) {
        continue;
      }

      if (candidate.fullName || candidate.primarySkills) {
        return candidate;
      }

      if (typeof candidate.text === 'object' && candidate.text !== null) {
        if (!candidate.text.error) return candidate.text;
      }
    }

    if (typeof candidate === 'string' && candidate.trim()) {
      const cleaned = candidate
        .replace(/^```(?:json)?\s*/i, '')
        .replace(/\s*```$/, '')
        .trim();

      try {
        const parsed = JSON.parse(cleaned);
        if (parsed.fullName || parsed.primarySkills) return parsed;
      } catch {}
    }
  }

  // OpenAI Responses API output format.
  if (Array.isArray(data.output)) {
    for (const item of data.output) {
      for (const part of item.content ?? []) {
        if (part.type === 'output_text') {
          if (typeof part.text === 'object' && part.text !== null) {
            if (part.text.error) {
              throw new Error(
                `Resume parsing failed: ${part.text.error}`
              );
            }
            return part.text;
          }

          if (typeof part.text === 'string') {
            try {
              return JSON.parse(part.text);
            } catch {}
          }
        }
      }
    }
  }

  throw new Error(
    'Could not parse resume JSON from Message a model. Check that node output.'
  );
}

const resume = getAIContent(ai);

// The job query returns a single row from job_requisitions.
const job = jobOutput;

// Validate that the node returned a job requisition.
if (!job.job_id || !job.title) {
  throw new Error(
    'Get Job Requisition did not return a job record. Check its SQL query and output.'
  );
}

// Read required skills from the actual database field.
const rawRequiredSkills =
  job.required_skills ??
  job.requiredSkills ??
  job.skills ??
  [];

const requiredSkills = Array.isArray(rawRequiredSkills)
  ? rawRequiredSkills.map(s => String(s).trim()).filter(Boolean)
  : String(rawRequiredSkills)
      .split(/[,;\n]/)
      .map(s => s.trim())
      .filter(Boolean);

// Normalize skill names for comparison.
const normalize = value =>
  String(value ?? '').toLowerCase().trim().replace(/\s+/g, ' ');

const candidateSkills = Array.isArray(resume.primarySkills)
  ? resume.primarySkills.map(s => String(s).trim()).filter(Boolean)
  : [];

const skillsFound = requiredSkills.filter(required =>
  candidateSkills.some(candidate =>
    normalize(candidate) === normalize(required)
  )
);

const skillsMissing = requiredSkills.filter(required =>
  !skillsFound.some(found => normalize(found) === normalize(required))
);

// Score based on required skills.
const matchScore = requiredSkills.length
  ? Math.round((skillsFound.length / requiredSkills.length) * 100)
  : 0;

// Check minimum experience.
const minExperience = Number(
  job.min_experience_years ?? job.minExperienceYears ?? 0
);

const candidateExperience = Number(resume.totalExperienceYears ?? 0);

const experienceMeetsRequirement =
  candidateExperience >= minExperience;

// Recommendation is an assessment, not an automatic hiring decision.
let recommendation;

if (!requiredSkills.length) {
  recommendation = 'Needs Review';
} else if (
  matchScore >= 70 &&
  experienceMeetsRequirement
) {
  recommendation = 'Strong Match';
} else if (
  matchScore >= 40 &&
  experienceMeetsRequirement
) {
  recommendation = 'Potential Match';
} else {
  recommendation = 'Recruiter Review';
}

const recommendationRationale =
  `Evaluated for ${job.title} (${job.job_id}). ` +
  `Matched ${skillsFound.length} of ${requiredSkills.length} required skills ` +
  `(${matchScore}%). ` +
  (skillsFound.length
    ? `Skills found: ${skillsFound.join(', ')}. `
    : 'No required skills matched. ') +
  (skillsMissing.length
    ? `Skills missing: ${skillsMissing.join(', ')}. `
    : 'All listed required skills were found. ') +
  `Candidate experience: ${candidateExperience} years; ` +
  `minimum required: ${minExperience} years. ` +
  (experienceMeetsRequirement
    ? 'Experience requirement met. '
    : 'Experience requirement not met. ') +
  `Assessment: ${recommendation}. Recruiter review is required before any rejection or interview dispatch.`;

// Return resume data plus evaluation results.
return [
  {
    json: {
      ...resume,
      jobId: job.job_id,
      jobTitle: job.title,
      matchScore,
      skillsFound,
      skillsMissing,
      minExperienceYears: minExperience,
      experienceMeetsRequirement,
      recommendation,
      recommendationRationale,
      jobRequisition: job,
    },
  },
];
